xml.Script:
        include 'Figures\Scripts\Cube_Standard_Colors.inc';

        R := 0.6;
        H := R / 3;
        H2 := H + 0.002;

        for i := 0 to 3 do begin
            ax[i] := R * cos(Pi / 2 * i);
            ay[i] := R * sin(Pi / 2 * i);
        end;

        D := R / 3;
        DC := R / sqrt(2);

        N := 40;
        for i := 0 to N - 1 do begin
            x[i] := R * cos(2 * Pi / N * i);
            y[i] := R * sin(2 * Pi / N * i);
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

Macro.Script:
i1 := i mod N;
i2 := (i + 1) mod N;
Inc(i);
